import Foundation
public struct EvaartaTransfer:Sendable { public let id:String; public let contentHash:String; public let totalChunks:Int; public let received:Set<Int>; public let state:String; public init(id:String,contentHash:String,totalChunks:Int,received:Set<Int>=[],state:String="queued"){self.id=id;self.contentHash=contentHash;self.totalChunks=totalChunks;self.received=received;self.state=state} }
public enum EvaartaArtifactSync { public static func accept(_ t:EvaartaTransfer,index:Int)->EvaartaTransfer{precondition(index>=0&&index<t.totalChunks);let r=t.received.union([index]);return EvaartaTransfer(id:t.id,contentHash:t.contentHash,totalChunks:t.totalChunks,received:r,state:r.count==t.totalChunks ? "complete":"transferring")} public static func missing(_ t:EvaartaTransfer)->[Int]{(0..<t.totalChunks).filter{!t.received.contains($0)}} public static func plan(local:Set<String>,peer:Set<String>)->(request:Set<String>,offer:Set<String>){(local.subtracting(peer),peer.subtracting(local))} public static func contract()->[String]{["offline-queue","resumable","missing-chunks","deterministic-reconciliation","store-and-forward","device-to-device"]} }